import getpass,hashlib,json,os,subprocess,time
from datetime import datetime,timezone
from pathlib import Path
ROOT=Path('/public/home/zqchen/projects/ECNU_EYU_data/work_space/S2/experimental_unvalidated/s2_rc_train_batch1_20261112_r1')
RUNS=['B0p_f0', 'B0p_f1', 'B0p_f2', 'B0p_f3', 'B0p_f4', 'BL_f0', 'BL_f1', 'BL_f2', 'BL_f3', 'BL_f4', 'BU_f0', 'BU_f1', 'BU_f2', 'BU_f3', 'BU_f4', 'BUL_f3', 'BUL_f4']
OLD={'B0p_f0': '4389556', 'B0p_f1': '4389557', 'B0p_f2': '4389558', 'B0p_f3': '4389559', 'B0p_f4': '4389560', 'BL_f0': '4389561', 'BL_f1': '4389562', 'BL_f2': '4389563', 'BL_f3': '4389564', 'BL_f4': '4389565', 'BU_f0': '4389566', 'BU_f1': '4389567', 'BU_f2': '4389568', 'BU_f3': '4389569', 'BU_f4': '4389570', 'BUL_f3': '4389574', 'BUL_f4': '4389575'}
errors=[]
def cmd(argv,timeout=90):
 p=subprocess.run(argv,capture_output=True,text=True,timeout=timeout)
 return {'argv':argv,'returncode':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
started=datetime.now(timezone.utc).isoformat()
assert ROOT.is_dir() and ROOT.resolve()==ROOT
run=json.loads((ROOT/'RUN.json').read_text())
sources={}
for name in ('operator/submit.py','operator/release.py','runtime/launch_run.py','runtime/p3.py','slurm/30_train.slurm','MANIFEST.sha256'):
 p=ROOT/name
 if not p.is_file() or p.is_symlink(): errors.append('missing_or_redirected:'+name); continue
 raw=p.read_bytes()
 if len(raw)>2_000_000: errors.append('source_too_large:'+name); continue
 sources[name]={'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw),'text':raw.decode(errors='replace')}
q=cmd(['squeue','--array','-u',getpass.getuser(),'-h','-o','%i|%j|%P|%T|%M|%S|%R|%Z'])
a=cmd(['sacct','-X','-n','-P','-u',getpass.getuser(),'-S','2026-11-15','--format=JobIDRaw,JobName%100,Partition,State,ExitCode,Submit,Start,End,Elapsed,WorkDir%500'])
si=cmd(['sinfo','-N','-h','-p','a100','-o','%N|%T|%G|%C'])
for label,obj in [('squeue',q),('sacct',a),('sinfo',si)]:
 if obj['returncode']: errors.append(label+'_failed')
queue=[]
for line in q['stdout'].splitlines():
 cells=line.split('|')
 if len(cells)==8 and cells[1].startswith('rcb_'): queue.append(dict(zip(['job_id','name','partition','state','elapsed','start','reason','work_dir'],[x.strip() for x in cells])))
history=[]
for line in a['stdout'].splitlines():
 cells=line.split('|')
 if cells and cells[-1]=='': cells.pop()
 if len(cells)!=10: errors.append('unparsed_sacct_line'); continue
 row=dict(zip(['job_id','name','partition','state','exit_code','submit','start','end','elapsed','work_dir'],[x.strip() for x in cells]))
 if row['job_id'] in OLD.values() or row['name'].startswith('rcb_'):
  history.append(row)
markers={}
for name in RUNS:
 paths=sorted((ROOT/'evidence').glob('RUN_'+name+'_*.json'))
 records=[]
 for p in paths:
  if p.is_symlink() or not p.is_file() or p.stat().st_size>2_000_000:
   errors.append('invalid_marker:'+p.name); continue
  raw=p.read_bytes()
  try: value=json.loads(raw)
  except Exception: errors.append('invalid_json:'+p.name); continue
  records.append({'name':p.name,'sha256':hashlib.sha256(raw).hexdigest(),'status':value.get('status'),
      'job_id':value.get('job_id'),'attempt':value.get('attempt'),'node':value.get('node'),
      'started_utc':value.get('started_utc'),'ended_utc':value.get('ended_utc'),
      'error':value.get('error'),'child_returncode':(value.get('cleanup') or {}).get('child_returncode')})
 markers[name]=records
manifest=sources.get('MANIFEST.sha256',{}).get('text','')
manifest_lines=[x for x in manifest.splitlines() if x.strip()]
manifest_sha=sources.get('MANIFEST.sha256',{}).get('sha256')
raw_submit=sources.get('operator/submit.py',{}).get('text','')
required_terms={term:term in raw_submit for term in ('def noshm','--dry-run','--hold','excluded','exclude_nodes','after_any')}
out={'status':'pass' if not errors else 'query_incomplete','artifact_status':'experimental_unvalidated','operator_approved':False,'formal_gate_status':'not_run_not_passed',
 'remote_started_utc':started,'remote_utc':datetime.now(timezone.utc).isoformat(),'user':getpass.getuser(),'root':str(ROOT),
 'experiment_id':run.get('experiment_id'),'manifest_sha256':manifest_sha,'manifest_entries':len(manifest_lines),
 'run_contract':{'shm':run.get('shm'),'resources':run.get('resources'),'max_concurrent':run.get('max_concurrent'),'runs':{x:next((r for r in run.get('runs',[]) if r.get('name')==x),None) for x in RUNS}},
 'sources':sources,'submitter_static_terms':required_terms,'queue_rcb':queue,'history_rcb_and_original':history,
 'a100_nodes':si['stdout'],'markers':markers,'errors':errors,
 'boundaries':{'read_only_remote':True,'no_remote_file_writes':True,'no_job_changes':True,'no_image_or_checkpoint_reads':True}}
print(json.dumps(out,sort_keys=True))
